package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class WorkTasksAcceptance {
 static String api(String id){return "/api/openservice/records/incident/"+id+"/work-tasks";}
 static Map<String,Object> page(WorkflowSupport h,String id)throws Exception{return ProblemInvestigationsAcceptance.result(h.get(api(id),auth("admin")));}
 static Map<String,Object> task(Map<String,Object> page,String id){return objects(page.get("tasks")).stream().filter(t->t.get("task_id").equals(id)).findFirst().orElseThrow();}
 static Map<String,Object> command(WorkflowSupport h,String id,String operation,String task)throws Exception{var p=page(h,id);var b=map("operation",operation,"revision",task.isEmpty()?object(p.get("plan")).get("revision"):task(p,task).get("revision"),"record_revision",ProblemInvestigationsAcceptance.revision(object(p.get("parent"))));if(!task.isEmpty())b.put("task_id",task);return b;}
 static Map<String,Object> send(WorkflowSupport h,String id,Map<String,Object> b,String user)throws Exception{return ProblemInvestigationsAcceptance.result(h.json("POST",api(id),b,auth(user)));}
 static void configure(WorkflowSupport h,String id)throws Exception{var b=command(h,id,"configure","");b.put("close_at","6");send(h,id,b,"admin");}
 static Map<String,Object> creation(WorkflowSupport h,String id,String group,List<String> before,boolean required)throws Exception{var b=command(h,id,"create","");b.putAll(map("summary","Task <script> "+before.size(),"details","Perform and verify the planned work","group_id",group,"required",required,"predecessors",before));return b;}
 static String create(WorkflowSupport h,String id,String group,List<String> before,boolean required)throws Exception{return objects(send(h,id,creation(h,id,group,before,required),"admin").get("tasks")).getLast().get("task_id").toString();}
 static Map<String,Object> act(WorkflowSupport h,String id,String task,String operation,String user,String value)throws Exception{var b=command(h,id,operation,task);if(operation.equals("complete"))b.put("outcome",value);if(Set.of("cancel","requeue","waive").contains(operation))b.put("reason",value);return send(h,id,b,user);}
 static void state(WorkflowSupport h,String id,String state,int status)throws Exception{var r=h.json("PATCH","/api/now/table/incident/"+id,map("state",state),auth("admin"));assertEquals(status,r.statusCode(),html(r));}
 static String setup(WorkflowSupport h)throws Exception{for(String user:List.of("TaskOne","TaskTwo","TaskOther"))h.account(user,"agent");h.account("TaskReader","reader");String group=h.add("sys_user_group").get("sys_id").toString();for(String user:List.of("TaskOne","TaskTwo")){String uid;try(var db=h.store.open()){uid=RecordAccess.owner(db,user);}RecordScopesAcceptance.member(h,group,uid,true);}return group;}
 static void run(WorkflowSupport h)throws Exception{
  String group=setup(h),id=h.add("incident").get("sys_id").toString();assertEquals(409,h.json("POST",api(id),creation(h,id,group,List.of(),true),auth("admin")).statusCode());var config=command(h,id,"configure","");config.put("close_at","6");send(h,id,config,"admin");assertEquals(409,h.json("POST",api(id),config,auth("admin")).statusCode());String a=create(h,id,group,List.of(),true),b=create(h,id,group,List.of(a),true);assertEquals(false,task(page(h,id),b).get("ready"));
  var queue=ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks?limit=1",auth("TaskOne")));assertEquals(2,((Number)queue.get("total")).intValue());assertNotNull(queue.get("next_offset"));assertEquals(1,objects(queue.get("items")).size());assertNull(ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks?limit=1&offset=1",auth("TaskOne"))).get("next_offset"));assertEquals(0,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("TaskOther"))).get("total")).intValue());assertEquals(2,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("admin"))).get("total")).intValue());
  assertEquals(409,h.json("POST",api(id),command(h,id,"claim",b),auth("TaskOne")).statusCode());var premature=command(h,id,"complete",a);premature.put("outcome","Not started");assertEquals(409,h.json("POST",api(id),premature,auth("TaskOne")).statusCode());assertEquals(403,h.json("POST",api(id),command(h,id,"claim",a),auth("TaskOther")).statusCode());var claim=command(h,id,"claim",a);send(h,id,claim,"TaskOne");assertEquals(409,h.json("POST",api(id),claim,auth("TaskOne")).statusCode());assertEquals(409,h.json("POST",api(id),command(h,id,"claim",a),auth("TaskOne")).statusCode());
  var finish=command(h,id,"complete",a);finish.put("outcome","Verified");assertEquals(403,h.json("POST",api(id),finish,auth("TaskTwo")).statusCode());String one;try(var db=h.store.open()){one=RecordAccess.owner(db,"TaskOne");}RecordScopesAcceptance.member(h,group,one,false);assertEquals(403,h.json("POST",api(id),finish,auth("TaskOne")).statusCode());RecordScopesAcceptance.member(h,group,one,true);
  var requeue=command(h,id,"requeue",a);requeue.put("reason","Reassign unavailable worker");assertEquals(403,h.json("POST",api(id),requeue,auth("TaskTwo")).statusCode());send(h,id,requeue,"admin");assertEquals("",task(page(h,id),a).get("assignee_id"));act(h,id,a,"claim","TaskTwo","");act(h,id,a,"complete","TaskTwo","Verified production health");assertEquals(true,task(page(h,id),b).get("ready"));
  state(h,id,"2",200);state(h,id,"6",409);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var parent=Service.record(db,"incident",id);object(parent.get("data")).put("state","7");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,parent)).status);}assertEquals(409,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());act(h,id,b,"claim","TaskOne","");act(h,id,b,"complete","TaskOne","Dependencies and outcome checked");new Store(h.environment);assertEquals("Dependencies and outcome checked",task(page(h,id),b).get("outcome"));state(h,id,"6",200);assertEquals(409,h.json("POST",api(id),creation(h,id,group,List.of(),false),auth("admin")).statusCode());state(h,id,"2",200);
  String optional=create(h,id,group,List.of(),false);act(h,id,optional,"cancel","TaskOne","No longer needed");state(h,id,"6",200);state(h,id,"7",200);assertEquals(204,h.json("DELETE","/api/now/table/incident/"+id,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_case_task"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_task_plan"));}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  String group=setup(h),id=h.add("incident").get("sys_id").toString();assertEquals(403,h.get(api(id),auth("TaskReader")).statusCode());assertEquals(403,h.get("/api/openservice/work-tasks",auth("TaskReader")).statusCode());assertEquals(405,h.json("POST","/api/openservice/work-tasks",map(),auth("admin")).statusCode());assertEquals(400,h.get("/api/openservice/work-tasks?q=x",auth("admin")).statusCode());assertEquals(400,h.get("/api/openservice/work-tasks?limit=0",auth("admin")).statusCode());assertEquals(405,h.json("PATCH",api(id),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(id)+"?extra=1",auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id),map("operation","wrong"),auth("admin")).statusCode());var invalid=command(h,id,"configure","");invalid.put("close_at","absent");assertEquals(400,h.json("POST",api(id),invalid,auth("admin")).statusCode());invalid.put("extra",true);assertEquals(400,h.json("POST",api(id),invalid,auth("admin")).statusCode());configure(h,id);
  var create=creation(h,id,group,List.of(),true);for(var field:List.of(map("required","true"),map("predecessors","wrong"),map("predecessors",Collections.nCopies(21,"f".repeat(32))),map("summary"," "),map("details","x".repeat(4001)),map("group_id","f".repeat(32)),map("record_revision",-1))){var bad=new LinkedHashMap<>(create);bad.putAll(field);int expected=field.containsKey("group_id")?404:400;assertEquals(expected,h.json("POST",api(id),bad,auth("admin")).statusCode());}
  String a=create(h,id,group,List.of(),true);var duplicate=creation(h,id,group,List.of(a,a),true);assertEquals(400,h.json("POST",api(id),duplicate,auth("admin")).statusCode());String b=create(h,id,group,List.of(a),true);String another=h.add("incident").get("sys_id").toString();configure(h,another);assertEquals(404,h.json("POST",api(another),creation(h,another,group,List.of(a),true),auth("admin")).statusCode());var missing=command(h,id,"claim",a);missing.put("task_id","f".repeat(32));assertEquals(404,h.json("POST",api(id),missing,auth("admin")).statusCode());
  var revise=command(h,id,"revise",a);revise.putAll(map("summary","Revise first","details","New instructions","group_id",group,"predecessors",List.of(b)));assertEquals(400,h.json("POST",api(id),revise,auth("admin")).statusCode());revise.put("predecessors",List.of());send(h,id,revise,"TaskOne");assertEquals("Revise first",task(page(h,id),a).get("summary"));act(h,id,a,"claim","TaskOne","");revise=command(h,id,"revise",a);revise.putAll(map("summary","Invalid working edit","details","x","group_id",group,"predecessors",List.of()));assertEquals(409,h.json("POST",api(id),revise,auth("admin")).statusCode());
  var cancel=command(h,id,"cancel",a);cancel.put("reason","Wrong worker");assertEquals(403,h.json("POST",api(id),cancel,auth("TaskTwo")).statusCode());cancel.put("reason"," ");assertEquals(400,h.json("POST",api(id),cancel,auth("TaskOne")).statusCode());cancel.put("reason","Work superseded");send(h,id,cancel,"TaskOne");assertEquals(409,h.json("POST",api(id),command(h,id,"claim",a),auth("admin")).statusCode());cancel=command(h,id,"cancel",a);cancel.put("reason","Already cancelled");assertEquals(409,h.json("POST",api(id),cancel,auth("admin")).statusCode());assertEquals(400,h.json("POST",api(id),creation(h,id,group,List.of(a),true),auth("admin")).statusCode());
  var waive=command(h,id,"waive",a);waive.put("reason","Superseded work reviewed");assertEquals(403,h.json("POST",api(id),waive,auth("TaskOne")).statusCode());send(h,id,waive,"admin");waive=command(h,id,"waive",a);waive.put("reason","Already waived");assertEquals(409,h.json("POST",api(id),waive,auth("admin")).statusCode());assertEquals(409,h.json("POST",api(id),command(h,id,"claim",b),auth("TaskOne")).statusCode());revise=command(h,id,"revise",b);revise.putAll(map("summary","Replacement verification","details","Review new evidence","group_id",group,"predecessors",List.of()));send(h,id,revise,"admin");var requeue=command(h,id,"requeue",b);requeue.put("reason","Not working");assertEquals(409,h.json("POST",api(id),requeue,auth("admin")).statusCode());act(h,id,b,"claim","admin","");var emptyOutcome=command(h,id,"complete",b);emptyOutcome.put("outcome","");assertEquals(400,h.json("POST",api(id),emptyOutcome,auth("admin")).statusCode());act(h,id,b,"complete","admin","Replacement passed");waive=command(h,id,"waive",b);waive.put("reason","Completed work");assertEquals(409,h.json("POST",api(id),waive,auth("admin")).statusCode());state(h,id,"2",200);state(h,id,"6",200);
  String limit=h.add("incident").get("sys_id").toString();configure(h,limit);try(var db=h.store.open()){for(int n=1;n<=100;n++)db.update("INSERT INTO os_case_task(task_id,parent_id,ordinal,summary,details,group_id,assignee_id,state,required,predecessors,outcome,note,revision) VALUES(?,?,?,'Limit task','Instructions',?,'','queued',0,'[]','','',0)",Values.id(),limit,n,group);db.connection.commit();}assertEquals(400,h.json("POST",api(limit),creation(h,limit,group,List.of(),false),auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception{
  String group=setup(h),id=h.add("incident").get("sys_id").toString();configure(h,id);String a=create(h,id,group,List.of(),true);Map<String,Object> original,groups;try(var db=h.store.open()){original=Service.schema(db,"incident");groups=Service.schema(db,"sys_user_group");}
  assertEquals(false,task(ProblemInvestigationsAcceptance.result(h.get(api(id),auth("TaskOther"))),a).get("can_work"));
  for(String field:List.of("description","state")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,h.get(api(id),auth("TaskOne")).statusCode());assertEquals(403,h.json("POST",api(id),command(h,id,"claim",a),auth("TaskOne")).statusCode());assertEquals(0,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("TaskOne"))).get("total")).intValue());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}}
  var schema=new LinkedHashMap<>(groups);schema.put("record_roles",map("read",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"sys_user_group",schema);try{var p=ProblemInvestigationsAcceptance.result(h.get(api(id),auth("TaskOne")));assertTrue(object(p.get("groups")).isEmpty());assertEquals("Restricted or unavailable team",task(p,a).get("group_name"));}finally{ReferencePickerAcceptance.writeSchema(h,"sys_user_group",groups);}
  schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{assertEquals(403,h.json("POST",api(id),creation(h,id,group,List.of(),true),auth("TaskOne")).statusCode());act(h,id,a,"claim","TaskOne","");act(h,id,a,"complete","TaskOne","Worker can finish without managing case configuration");}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  String denied=create(h,id,group,List.of(),true);String owner;try(var db=h.store.open()){owner=RecordAccess.owner(db,"admin");}ProblemInvestigationsAcceptance.access(h,"incident",id,"private",owner);assertEquals(404,h.get(api(id),auth("TaskOne")).statusCode());assertEquals(404,h.json("POST",api(id),command(h,id,"claim",denied),auth("TaskOne")).statusCode());assertEquals(0,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("TaskOne"))).get("total")).intValue());ProblemInvestigationsAcceptance.access(h,"incident",id,"workspace","");
  schema=new LinkedHashMap<>(original);schema.put("field_rules",map("description",map("type","string","required",true)));ReferencePickerAcceptance.writeSchema(h,"incident",schema);try{var attempt=creation(h,id,group,List.of(),true);assertEquals(400,h.json("POST",api(id),attempt,auth("admin")).statusCode());assertEquals(2,objects(page(h,id).get("tasks")).size());assertEquals(attempt.get("revision"),object(page(h,id).get("plan")).get("revision"));}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  String problem=h.add("problem").get("sys_id").toString(),change=h.add("change_request").get("sys_id").toString();assertAll("Missing form choices return validation errors",
   ()->assertEquals(400,h.protectedForm("/record/problem/"+problem+"/investigation",map("revision",0,"record_revision",0,"cause","Cause","workaround","Workaround"),auth("admin")).statusCode()),
   ()->assertEquals(400,h.protectedForm("/record/change_request/"+change+"/plan",map("revision",0,"record_revision",0,"implementation","Deploy","impact","Restart","backout","Restore","test","Verify","impact_score",1,"likelihood",1),auth("admin")).statusCode()),
   ()->assertEquals(400,h.protectedForm("/record/incident/"+id+"/work-tasks",map("revision",0,"record_revision",0),auth("admin")).statusCode()));
  var restrictedTable=new LinkedHashMap<>(original);restrictedTable.put("record_roles",map("read",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"incident",restrictedTable);try{assertEquals(0,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("admin"))).get("total")).intValue());assertEquals(1,((Number)ProblemInvestigationsAcceptance.result(h.get("/api/openservice/work-tasks",auth("TaskOne"))).get("total")).intValue());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  var removedState=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));object(removedState.get("states")).remove("1");object(removedState.get("flow")).remove("1");ReferencePickerAcceptance.writeSchema(h,"incident",removedState);try{assertEquals(false,page(h,id).get("mutable"),"Unrecognized parent state cannot authorize task mutations");assertEquals(409,h.json("POST",api(id),command(h,id,"claim",denied),auth("TaskOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",original);}
  var form=command(h,id,"create","");form.putAll(map("summary","Form","details","Instructions","group_id",group,"required","yes"));assertEquals(400,h.protectedForm("/record/incident/"+id+"/work-tasks",form,auth("admin")).statusCode());form.put("required","true");form.put("predecessor_"+a,"false");assertEquals(400,h.protectedForm("/record/incident/"+id+"/work-tasks",form,auth("admin")).statusCode());
 }
}
